'use strict';

// MODULES //

var db = require( '@stdlib/math/special/data/unary_function_database.json' );
var dtypes = require( '@stdlib/ndarray/dtypes' );
var mostlySafeCasts = require( '@stdlib/ndarray/mostly-safe-casts' );
var contains = require( '@stdlib/array/base/assert/contains' );
var getAliasPrefix = require( './get_alias_prefix.js' );
var selectScalarKernel = require( './select_scalar_kernel.js' );
var selectKernelName = require( './select_kernel_name.js' );


// MAIN //

/**
* Generates dtype mappings for a given base package.
*
* @private
* @param {string} basePkg - base package name
* @returns {Array} array of mappings
*
* @example
* var mappings = generateDtypes( 'acosd' );
* // returns [ [ 'float32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_f_d_as_d_d' ],... ]
*/
function generateDtypes( basePkg ) {
	var needsPromotion;
	var cFunctionName;
	var allowedCasts;
	var scalarKernel;
	var outputDtype;
	var inputDtype;
	var kernelName;
	var mappings;
	var filtered;
	var obj;
	var odt;
	var idt;
	var i;
	var j;
	var k;

	mappings = [];

	// Get scalar kernels and configuration for this function:
	obj = db[ basePkg ];

	// Get input dtypes:
	idt = dtypes( obj.input_dtypes );

	// Get output dtypes:
	odt = dtypes( obj.output_dtypes );

	// Filter out excluded dtypes:
	filtered = [];
	for ( i = 0; i < idt.length; i++ ) {
		if ( !contains( obj.excluded_dtypes, idt[ i ] ) ) {
			filtered.push( idt[ i ] );
		}
	}
	idt = filtered;

	// Generate all mostly-safe cast combinations:
	for ( i = 0; i < idt.length; i++ ) {
		inputDtype = idt[ i ];

		if ( inputDtype === 'generic' ) {
			allowedCasts = [ 'generic' ];
		} else {
			// Get all dtypes this input can be mostly-safely cast to:
			allowedCasts = mostlySafeCasts( inputDtype );
		}

		// Remove the dtypes which are not allowed for output:
		filtered = [];
		for ( k = 0; k < allowedCasts.length; k++ ) {
			if ( contains( odt, allowedCasts[ k ] ) ) {
				filtered.push( allowedCasts[ k ] );
			}
		}
		allowedCasts = filtered;

		for ( j = 0; j < allowedCasts.length; j++ ) {
			outputDtype = allowedCasts[ j ];

			if ( contains( obj.excluded_dtypes, outputDtype ) ) {
				continue;
			}

			// Get scalar kernel for this dtype combination:
			scalarKernel = selectScalarKernel( obj.scalar_kernels, outputDtype, inputDtype ); // eslint-disable-line max-len

			// Generate ndarray kernel name:
			kernelName = selectKernelName( inputDtype, outputDtype, scalarKernel ); // eslint-disable-line max-len

			// Generate mapping:
			needsPromotion = inputDtype !== outputDtype;

			// Extract the function name and create C function name:
			cFunctionName = scalarKernel.split( '/' ).pop();
			cFunctionName = getAliasPrefix( scalarKernel ) + cFunctionName;

			mappings.push([
				inputDtype,
				outputDtype,
				scalarKernel,
				needsPromotion,
				( needsPromotion ) ? outputDtype : null,
				( needsPromotion ) ? outputDtype : null,
				cFunctionName,
				kernelName
			]);
		}
	}

	return mappings;
}


// EXPORTS //

module.exports = generateDtypes;
